using PVZEngine.Tools.Timing;
using UnityEngine;

namespace MVZ2.GameContent.Contraptions
{
    [AutoEntityBehaviourDefinition(VanillaEntityBehaviourNames.teleporter_Evoke)]
    public class Teleporter_Evoke : ContraptionEvokeBehaviour
    {
        public Teleporter_Evoke(string nsp, string name) : base(nsp, name)
        {
        }
        public override void Update(Entity entity)
        {
            base.Update(entity);
            if (entity.IsEvoked())
            {
                EvokedUpdate(entity);
            }
        }
        private void EvokedUpdate(Entity pad)
        {
            // ¥Û’–µπº∆ ±°£
            var timer = GetEvocationTimer(pad);
            if (timer == null)
            {
                timer = TimerHelper.NewSecondTimer(EVOCATION_DURATION_SECONDS);
                SetEvocationTimer(pad, timer);
            }
            timer.Run();

            var level = pad.Level;
            var heldItemData = level.GetHeldItemData();
            bool holdingThis = heldItemData != null && heldItemData.Type == VanillaHeldTypes.teleporterEvocation && heldItemData.GetEntityID() == pad.ID;
            if (timer.Expired || !holdingThis)
            {
                if (holdingThis)
                {
                    level.ResetHeldItem();
                }
                pad.SetEvoked(false);
            }
        }
        public override void Evoke(Entity entity)
        {
            var level = entity.Level;
            entity.SetEvoked(true);

            var builder = new HeldItemBuilder(VanillaHeldTypes.teleporterEvocation, 100);
            builder.SetEntityID(entity.ID);
            builder.SetCannotCancel(true);
            entity.Level.SetHeldItem(builder);

            var timer = GetEvocationTimer(entity);
            if (timer == null)
            {
                timer = TimerHelper.NewSecondTimer(EVOCATION_DURATION_SECONDS);
                SetEvocationTimer(entity, timer);
            }
            else
            {
                timer.ResetSeconds(EVOCATION_DURATION_SECONDS);
            }

            entity.PlaySound(VanillaSoundID.teleporterSignal);

            SummonBlackUFOIfPossible(entity);
        }
        public static void TeleportTeam(Entity teleporter, LawnGrid grid)
        {
            var level = teleporter.Level;
            var width = WIDTH;
            var height = HEIGHT;
            var xOffset = X_OFFSET;
            var yOffset = Y_OFFSET;

            for (int x = 0; x < width; x++)
            {
                for (int y = 0; y < height; y++)
                {
                    var index = x + y * width;
                    var team = GetTeleporterTeam(teleporter);
                    if (index < 0 || index >= team.tiles.Length)
                        continue;
                    var tile = team.tiles[index];
                    if (tile == null)
                        continue;
                    TeleportTeamTile(teleporter, tile, grid.Column + x + xOffset, grid.Lane + y + yOffset);
                }
            }
            teleporter.AddBuff<TeleporterTriggeredBuff>();
            teleporter.PlaySound(VanillaSoundID.teleportUp);
            teleporter.PlaySound(VanillaSoundID.chronoSphere);
        }
        public static void TeleportTeamTile(Entity teleporter, TeleporterTeamTileLevelData tile, int column, int lane)
        {
            foreach (var entity in tile.entities)
            {
                if (!NamespaceID.IsValid(entity))
                    continue;
                TeleportTeamMember(teleporter, entity, column, lane);
            }
        }
        public static Entity? TeleportTeamMember(Entity teleporter, NamespaceID memberID, int column, int lane)
        {
            var memberDefinition = teleporter.Level.Content.GetEntityDefinition(memberID);
            if (memberDefinition == null)
                return null;
            if (memberDefinition.Type == EntityTypes.ENEMY)
            {
                column = Mathf.Clamp(column, 0, teleporter.Level.GetMaxColumnCount() - 1);
                lane = Mathf.Clamp(lane, 0, teleporter.Level.GetMaxLaneCount() - 1);
                var grid = teleporter.Level.GetGrid(column, lane);
                if (grid != null)
                {
                    return teleporter.Spawn(memberDefinition, grid.GetEntityPosition())?.Let(e =>
                    {
                        e.AddBuff<TeleporterTeleportDownBuff>();
                    });
                }
            }
            else
            {
                var grid = teleporter.Level.GetGrid(column, lane);
                if (grid != null)
                {
                    CheckAquatic(teleporter, memberDefinition, grid);

                    return teleporter.Spawn(memberDefinition, grid.GetEntityPosition())?.Let(e =>
                    {
                        e.AddBuff<TeleporterTeleportDownBuff>();
                    });
                }
            }
            return null;
        }
        public static TeleporterTeamLevelData GetTeleporterTeam(Entity teleporter)
        {
            var team = teleporter.Level.GetCurrentTeleporterTeam();
            if (team == null)
            {
                if (DefaultTeam == null)
                {
                    DefaultTeam = CreateDefaultTeleporterTeam();
                }
                team = DefaultTeam;
            }
            return team;
        }
        public static void CheckAquatic(Entity teleporter, EntityDefinition memberDefinition, LawnGrid grid)
        {
            if (!grid.IsWater())
                return;
            var gridLayers = memberDefinition.GetGridLayersToTake();
            if (gridLayers != null && gridLayers.Contains(VanillaGridLayers.carrier))
                return;
            if (memberDefinition.CanContraptionOnWater())
                return;
            if (grid.GetEntities().Any(e => e.IsEntityOf(VanillaContraptionID.lilyPad)))
                return;
            teleporter.Spawn(VanillaContraptionID.lilyPad, grid.GetEntityPosition())?.Let(e =>
            {
                e.AddBuff<TeleporterTeleportDownBuff>();
                e.PlaySound(VanillaSoundID.teleportDown);
            });
        }
        public static TeleporterTeamLevelData CreateDefaultTeleporterTeam()
        {
            var tiles = new TeleporterTeamTileLevelData[WIDTH * HEIGHT];
            for (int i = 0; i < tiles.Length; i++)
            {
                if (i % 2 == 0)
                    continue;
                var entities = new NamespaceID[] { VanillaContraptionID.furnace };
                tiles[i] = new TeleporterTeamTileLevelData(entities);
            }
            return new TeleporterTeamLevelData(tiles);
        }
        public static Entity? SummonBlackUFOIfPossible(Entity teleporter)
        {
            var level = teleporter.Level;
            var artifactID = VanillaArtifactID.cowHorn;
            if (!level.IsPossibleToSpawnUnlockArtifactPickup(VanillaAreaID.ship, VanillaUnlockID.cowHorn, artifactID))
                return null;
            if (level.EntityExists(e => e.IsEntityOf(VanillaEnemyID.ufo) && e.GetVariant() == UndeadFlyingObject.VARIANT_BLACK))
                return null;
            if (level.EntityExists(VanillaEnemyID.zombieCow))
                return null;
            var lane = level.GetMaxLaneCount() / 2;
            var column = level.GetMaxColumnCount() - 1;
            var grid = level.GetGrid(column, lane);
            if (grid == null)
                return null;
            return UndeadFlyingObject.SpawnAtGrid(grid, UndeadFlyingObject.VARIANT_BLACK);
        }
        public static FrameTimer? GetEvocationTimer(Entity pad) => pad.GetProperty<FrameTimer>(PROP_EVOCATION_TIMER);
        public static void SetEvocationTimer(Entity pad, FrameTimer? value) => pad.SetProperty(PROP_EVOCATION_TIMER, value);
        public const float EVOCATION_DURATION_SECONDS = 5;
        public const int WIDTH = 3;
        public const int HEIGHT = 3;
        public const int X_OFFSET = -WIDTH / 2;
        public const int Y_OFFSET = -HEIGHT / 2;


        public static readonly VanillaEntityPropertyMeta<FrameTimer> PROP_EVOCATION_TIMER = new VanillaEntityPropertyMeta<FrameTimer>("evocation_timer");
        public static TeleporterTeamLevelData? DefaultTeam;
    }
}